function addr(f){ if(!f) return ''; if(typeof f==='string') return f; if(f.text) return f.text; if(Array.isArray(f.value)&&f.value[0]) return f.value[0].address||f.value[0].name||''; return ''; }
function str(x){ return typeof x==='string'?x:(x&&x.text)?x.text:''; }
const emails=[];
for(const item of $input.all()){
  const j=item.json;
  const sender=addr(j.From||j.from||(j.headers&&j.headers.from));
  const subject=str(j.Subject||j.subject||(j.headers&&j.headers.subject));
  let text=(typeof j.text==='string')?j.text:(j.textPlain||'');
  if(!text&&j.html) text=String(j.html).replace(/<[^>]+>/g,' ');
  if(!text) text=j.snippet||'';
  const dateRaw=j.date||j.internalDate||j.Date;
  let received_at;
  if(dateRaw){ const n=Number(dateRaw); received_at=new Date(isNaN(n)?dateRaw:n).toISOString(); } else { received_at=new Date().toISOString(); }
  emails.push({ gmail_msg_id:j.id||j.messageId, sender, subject, text, received_at });
}
return [{ json:{ emails } }];
